    def maturity_adjustment_basel_irb(self, *, pd: float, maturity: float) -> dict[str, Any]:
        """Basel IRB maturity adjustment (CRE31.6).

        ``b(PD) = (0.11852 - 0.05478 ln PD)^2`` and
        ``MA = (1 + (M - 2.5) b) / (1 - 1.5 b)``. At M = 2.5 the adjustment is
        exactly 1.0 by construction.

        Returns:
            The raw API response as a dict.
        """
        body = {"pd": pd, "maturity": maturity}
        return self._client._request(
            "POST", "/api/v1/credit-risk/maturity_adjustment_basel_irb", json_body=body
        )

    def point_in_time_pd_estimation(
        self, *, ttc_pd: float, macro_index: float, sensitivity: float = 1.0
    ) -> dict[str, Any]:
        """Derive a point-in-time PD from a TTC PD and a macro factor.

        Inverse of the TTC transform: shifts the probit-domain TTC score by a
        sensitivity-scaled standardised macro index ``z`` (negative ``z`` = adverse
        conditions raise the PD): ``score_PIT = N^{-1}(PD_TTC) - sensitivity * z``.

        Returns:
            The raw API response as a dict.
        """
        body = {"ttc_pd": ttc_pd, "macro_index": macro_index, "sensitivity": sensitivity}
        return self._client._request(
            "POST", "/api/v1/credit-risk/point_in_time_pd_estimation", json_body=body
        )

