    def retail_scorecard_pd_model(
        self,
        *,
        feature_values: list[float] | list[list[float]],
        points_per_feature: list[float] | list[list[float]],
        base_points: float,
        pdo: float = 50.0,
        base_score: float = 600.0,
        base_odds: float = 50.0,
    ) -> dict[str, Any]:
        """Retail scorecard: additive points to a PD via the points-to-double-odds map.

        A scorecard sums attribute points into a score; the score relates to odds by
        ``odds = base_odds * 2^{(score - base_score)/pdo}`` (PDO = points to double
        the odds). PD = ``1 / (1 + odds)``.

        Returns:
            The raw API response as a dict.
        """
        body = {
            "feature_values": feature_values,
            "points_per_feature": points_per_feature,
            "base_points": base_points,
            "pdo": pdo,
            "base_score": base_score,
            "base_odds": base_odds,
        }
        return self._client._request(
            "POST", "/api/v1/credit-risk/retail_scorecard_pd_model", json_body=body
        )

