    def standardised_approach_ccr_sa_ccr(
        self,
        *,
        mark_to_market: float,
        collateral: float,
        add_on_aggregate: float,
        alpha: float = 1.4,
    ) -> dict[str, Any]:
        """Basel SA-CCR EAD (CRE52).

        ``EAD = alpha * (RC + PFE)`` where the replacement cost is
        ``RC = max(MtM - collateral, 0)`` (unmargined) and ``PFE = multiplier *
        AddOn_aggregate`` with the regulatory recognition-of-excess-collateral
        multiplier ``multiplier = min(1, 0.05 + 0.95 * exp((MtM - C)/(1.9 * AddOn)))``.
        The supervisory ``alpha`` is 1.4.

        Returns:
            The raw API response as a dict.
        """
        body = {
            "mark_to_market": mark_to_market,
            "collateral": collateral,
            "add_on_aggregate": add_on_aggregate,
            "alpha": alpha,
        }
        return self._client._request(
            "POST", "/api/v1/credit-risk/standardised_approach_ccr_sa_ccr", json_body=body
        )

    def through_the_cycle_pd_adjustment(
        self, *, pit_pd: float, long_run_average_pd: float, cyclicality: float = 0.5
    ) -> dict[str, Any]:
        """Convert a point-in-time PD to a through-the-cycle PD.

        TTC PDs dampen the macro cycle for stable regulatory capital. A convex blend
        in the Gaussian-score (probit) domain is used so the result stays a valid
        probability: ``score_TTC = (1-w) score_PIT + w score_LRA`` with
        ``w = cyclicality`` and ``score = N^{-1}(PD)``.

        Returns:
            The raw API response as a dict.
        """
        body = {
            "pit_pd": pit_pd,
            "long_run_average_pd": long_run_average_pd,
            "cyclicality": cyclicality,
        }
        return self._client._request(
            "POST", "/api/v1/credit-risk/through_the_cycle_pd_adjustment", json_body=body
        )

    def unexpected_loss_ul_computation(
        self,
        *,
        pd: list[float] | list[list[float]],
        lgd: list[float] | list[list[float]],
        ead: list[float] | list[list[float]],
    ) -> dict[str, Any]:
        """Stand-alone Unexpected Loss per exposure and the un-diversified sum.

        For a Bernoulli default with deterministic LGD, the stand-alone UL of one
        exposure is ``EAD * LGD * sqrt(PD(1-PD))`` — the loss standard deviation.
        The portfolio UL reported here is the *sum* of stand-alone ULs (i.e. the
        fully-correlated upper bound); correlation-aware UL is handled by the
        Vasicek / CreditMetrics models in :mod:`engine.credit_var`.

        Returns:
            The raw API response as a dict.
        """
        body = {"pd": pd, "lgd": lgd, "ead": ead}
        return self._client._request(
            "POST", "/api/v1/credit-risk/unexpected_loss_ul_computation", json_body=body
        )

    def wrong_way_risk_adjustment(
        self, *, base_cva: float, correlation: float, exposure_volatility: float = 0.3
    ) -> dict[str, Any]:
        """Wrong-way-risk (WWR) multiplicative adjustment to CVA.

        When exposure rises as the counterparty's credit deteriorates (positive
        correlation), CVA is understated. A first-order alpha multiplier
        ``alpha = 1 + correlation * exposure_volatility`` (clamped >= 0) scales the
        base CVA; negative correlation gives right-way risk (alpha < 1).

        Returns:
            The raw API response as a dict.
        """
        body = {
            "base_cva": base_cva,
            "correlation": correlation,
            "exposure_volatility": exposure_volatility,
        }
        return self._client._request(
            "POST", "/api/v1/credit-risk/wrong_way_risk_adjustment", json_body=body
        )

    def xva_aggregation(
        self, *, cva: float, dva: float = 0.0, fva: float = 0.0, kva: float = 0.0, mva: float = 0.0
    ) -> dict[str, Any]:
        """Aggregate the XVA components into a total valuation adjustment.

        Sign convention (cost to the bank is positive, reducing the trade value):
        ``total_xva = CVA - DVA + FVA + KVA + MVA``. DVA is a benefit and so enters
        negatively. The adjusted price is ``risk_free_price - total_xva`` downstream.

        Returns:
            The raw API response as a dict.
        """
        body = {"cva": cva, "dva": dva, "fva": fva, "kva": kva, "mva": mva}
        return self._client._request("POST", "/api/v1/credit-risk/xva_aggregation", json_body=body)
